import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "cn";
import { type ComponentProps, useId } from "react";

import {
  Button as ShadcnButton,
  buttonVariants as shadcnButtonVariants,
} from "@/components/ui/button";

import { ButtonContent } from "./button-content";

const depthVariants = cva("relative", {
  variants: {
    variant: {
      default:
        "border-primary/60 text-primary-foreground bg-linear-to-b from-[color-mix(in_oklab,var(--color-primary),black_8%)] to-[color-mix(in_oklab,var(--color-primary),black_20%)] shadow-[inset_0_1px_0_rgba(255,255,255,0.28),0_1px_2px_rgba(0,0,0,0.18)] [corner-shape:squircle] hover:brightness-110 supports-[corner-shape:squircle]:rounded-[0.75rem]",
      outline:
        "border-border from-background to-muted text-foreground aria-expanded:from-secondary aria-expanded:to-secondary dark:from-input dark:to-muted bg-linear-to-b shadow-[inset_0_1px_0_rgba(255,255,255,0.7),0_1px_2px_rgba(0,0,0,0.06)] [corner-shape:squircle] hover:brightness-[0.97] supports-[corner-shape:squircle]:rounded-[0.75rem] dark:shadow-[inset_0_1px_0_rgba(255,255,255,0.06),0_1px_2px_rgba(0,0,0,0.4)] dark:hover:brightness-125",
      secondary:
        "border-foreground/60 from-foreground/85 to-foreground text-background hover:from-foreground/70 hover:to-foreground/85 bg-linear-to-b shadow-[inset_0_1px_0_rgba(255,255,255,0.28),0_1px_2px_rgba(0,0,0,0.18)] [corner-shape:squircle] supports-[corner-shape:squircle]:rounded-[0.75rem]",
      ghost: "",
      destructive:
        "border-destructive/60 from-destructive focus-visible:border-destructive/40 focus-visible:ring-destructive/20 dark:focus-visible:ring-destructive/40 bg-linear-to-b to-[color-mix(in_oklab,var(--color-destructive),black_12%)] text-white shadow-[inset_0_1px_0_rgba(255,255,255,0.28),0_1px_2px_rgba(0,0,0,0.18)] [corner-shape:squircle] hover:brightness-110 supports-[corner-shape:squircle]:rounded-[0.75rem] dark:from-[color-mix(in_oklab,var(--color-destructive),black_20%)] dark:to-[color-mix(in_oklab,var(--color-destructive),black_30%)]",
      link: "text-foreground",
    },
  },
  defaultVariants: {
    variant: "default",
  },
});

type ButtonVariantProps = VariantProps<typeof shadcnButtonVariants>;

function buttonVariants({
  className,
  ...props
}: ButtonVariantProps & { className?: string } = {}) {
  return cn(shadcnButtonVariants(props), depthVariants(props), className);
}

type ButtonProps = ComponentProps<typeof ShadcnButton> & {
  /** Swaps the label for bouncing dots while an action runs. */
  loading?: boolean;
  /**
   * Fills the button from the left, from 0 to 100, e.g. while a file
   * uploads. Set it back to `undefined` when the work is done: the bar fills
   * up and fades out. For work you can't measure, use `loading`.
   */
  progress?: number;
};

function Button({
  className,
  variant = "default",
  size = "default",
  loading = false,
  progress,
  disabled,
  focusableWhenDisabled,
  "aria-describedby": ariaDescribedBy,
  children,
  ...props
}: ButtonProps) {
  const hasProgress = progress !== undefined;
  const busy = loading || hasProgress;
  const progressTextId = useId();

  return (
    <ShadcnButton
      aria-busy={busy || undefined}
      aria-describedby={
        hasProgress
          ? [ariaDescribedBy, progressTextId].filter(Boolean).join(" ")
          : ariaDescribedBy
      }
      className={cn(
        depthVariants({ variant }),
        "has-data-[clip]:overflow-hidden",
        busy && "cursor-progress",
        className
      )}
      data-loading={loading ? "" : undefined}
      disabled={disabled || busy}
      focusableWhenDisabled={focusableWhenDisabled ?? busy}
      size={size}
      variant={variant}
      {...props}
    >
      <ButtonContent
        loading={loading}
        progress={progress}
        progressTextId={progressTextId}
      >
        {children}
      </ButtonContent>
    </ShadcnButton>
  );
}

export { Button, buttonVariants };
export type { ButtonProps };

"use client";

import { Progress as ProgressPrimitive } from "@base-ui/react/progress";
import { cn } from "cn";
import { useState } from "react";

const LOADING_DOTS = [
  { bounce: "[animation-delay:0ms]", enter: "[animation-delay:70ms]" },
  { bounce: "[animation-delay:140ms]", enter: "[animation-delay:110ms]" },
  { bounce: "[animation-delay:280ms]", enter: "[animation-delay:150ms]" },
] as const;

function useLoadingSwap(loading: boolean) {
  const [previousLoading, setPreviousLoading] = useState(loading);
  const [isSwapping, setIsSwapping] = useState(false);
  if (loading !== previousLoading) {
    setPreviousLoading(loading);
    setIsSwapping(true);
  }
  return { finishSwap: () => setIsSwapping(false), isSwapping };
}

function useProgressCompletion(hasProgress: boolean) {
  const [previousHasProgress, setPreviousHasProgress] = useState(hasProgress);
  const [isCompleting, setIsCompleting] = useState(false);
  if (hasProgress !== previousHasProgress) {
    setPreviousHasProgress(hasProgress);
    setIsCompleting(!hasProgress);
  }
  return { finishCompletion: () => setIsCompleting(false), isCompleting };
}

function ButtonProgress({
  completing,
  onFaded,
  value,
}: {
  completing: boolean;
  onFaded: () => void;
  value: number;
}) {
  return (
    <ProgressPrimitive.Root
      aria-hidden
      className={cn(
        "pointer-events-none absolute inset-0",
        completing && "animate-button-progress-out"
      )}
      data-slot="button-progress"
      onAnimationEnd={(event) => {
        if (event.target === event.currentTarget) {
          onFaded();
        }
      }}
      render={<span />}
      value={value}
    >
      <ProgressPrimitive.Track
        className="absolute inset-0 overflow-hidden"
        render={<span />}
      >
        <ProgressPrimitive.Indicator
          className="absolute inset-y-0 start-0 bg-current/15 transition-[width] duration-300 ease-[cubic-bezier(0.22,1,0.36,1)] motion-reduce:transition-none"
          render={<span />}
        />
      </ProgressPrimitive.Track>
    </ProgressPrimitive.Root>
  );
}

function ButtonLoader({
  entering,
  loading,
  onSwappedOut,
}: {
  entering: boolean;
  loading: boolean;
  onSwappedOut: () => void;
}) {
  return (
    <span
      aria-hidden
      className={cn(
        "pointer-events-none absolute inset-0 flex items-center justify-center gap-[0.2em]",
        !loading &&
          "animate-button-swap-out opacity-0 motion-reduce:animate-none"
      )}
      data-slot="button-loader"
      onAnimationEnd={(event) => {
        if (!loading && event.target === event.currentTarget) {
          onSwappedOut();
        }
      }}
    >
      {LOADING_DOTS.map(({ bounce, enter }) => (
        <span
          className={cn(
            "motion-reduce:animate-none",
            loading && entering && `animate-button-swap-in ${enter}`
          )}
          key={enter}
        >
          <span
            className={cn(
              "animate-button-dot block size-[0.3em] rounded-full bg-current motion-reduce:animate-none",
              bounce,
              !loading && "[animation-play-state:paused]"
            )}
          />
        </span>
      ))}
    </span>
  );
}

interface ButtonContentProps {
  children?: React.ReactNode;
  loading: boolean;
  progress: number | undefined;
  progressTextId: string;
}

function ButtonContent({
  children,
  loading,
  progress,
  progressTextId,
}: ButtonContentProps) {
  const hasProgress = progress !== undefined;
  const { finishSwap, isSwapping } = useLoadingSwap(loading);
  const { finishCompletion, isCompleting } = useProgressCompletion(hasProgress);
  const showLoader = loading || isSwapping;
  const showProgress = hasProgress || isCompleting;

  return (
    <>
      {showProgress && (
        <ButtonProgress
          completing={isCompleting}
          onFaded={finishCompletion}
          value={progress ?? 100}
        />
      )}
      {hasProgress && (
        <span hidden id={progressTextId}>
          {`${Math.round(progress)}%`}
        </span>
      )}
      {showLoader || showProgress ? (
        <span
          className={cn(
            "relative inline-flex min-w-0 flex-1 items-center [justify-content:inherit] [gap:inherit] motion-reduce:animate-none",
            loading && "opacity-0",
            isSwapping &&
              (loading
                ? "animate-button-swap-out"
                : "animate-button-swap-in [animation-delay:70ms]")
          )}
          data-clip=""
          data-slot="button-label"
        >
          {children}
        </span>
      ) : (
        children
      )}
      {showLoader && (
        <ButtonLoader
          entering={isSwapping}
          loading={loading}
          onSwappedOut={finishSwap}
        />
      )}
    </>
  );
}

export { ButtonContent };
